func TestBenchmarkRampJSONLocalOnly(t *testing.T) {
	stdout, stderr, err := runCLIForDocsTest(t, "benchmark", "ramp", "--json")
	if err != nil {
		t.Fatalf("benchmark ramp --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("benchmark ramp wrote stderr: %q", stderr)
	}

	var got benchmarkRampResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("benchmark ramp --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "benchmark ramp" || got.Benchmark == "" {
		t.Fatalf("wrong benchmark response: %#v", got)
	}
	if !got.Safety.GuidanceOnly || !got.Safety.LocalOnly || !got.Safety.NoAPICalls || !got.Safety.NoMCPExecution || !got.Safety.NoSecretsRead || !got.Safety.UsesRampAsReferenceOnly {
		t.Fatalf("benchmark safety should prove local guidance only: %#v", got.Safety)
	}
	if got.Safety.NoPublishing != true || got.Safety.DoesNotClaimPublicLaunch != true {
		t.Fatalf("benchmark should not claim public launch or publishing: %#v", got.Safety)
	}
	if strings.Contains(strings.ToLower(stdout), "bearer ") || strings.Contains(stdout, "STRADDLE_TOKEN=") || strings.Contains(stdout, "sk_live") || strings.Contains(stdout, "sk_test") {
		t.Fatalf("benchmark ramp should not emit token literals:\n%s", stdout)
	}

	for _, name := range []string{
		"OpenAPI-generated command coverage",
		"Agent-friendly output",
		"MCP readiness",
		"Documentation and discovery",
		"Credential guidance",
		"Presentation polish",
		"Operational workflows",
		"Distribution readiness",
	} {
		dimension, ok := benchmarkRampDimensionByName(got, name)
		if !ok {
			t.Fatalf("missing benchmark dimension %q: %#v", name, got.Dimensions)
		}
		if dimension.RampReference == "" || len(dimension.StraddleEvidence) == 0 || dimension.Status == "" {
			t.Fatalf("dimension %q should have reference, evidence, and status: %#v", name, dimension)
		}
	}
}

func TestBenchmarkRampHumanOutputShowsBlockers(t *testing.T) {
	var output bytes.Buffer
	cmd := &cobra.Command{}
	cmd.SetOut(&output)
	if err := printBenchmarkRampHuman(cmd, buildBenchmarkRampResponse()); err != nil {
		t.Fatalf("printBenchmarkRampHuman returned error: %v", err)
	}
	stdout := output.String()

	for _, want := range []string{
		"Ramp benchmark",
		"Safety: local guidance only.",
		"Agent-friendly output",
		"MCP readiness",
		"Presentation polish",
		"Public blockers:",
		"Public npm, npx, Homebrew, and GitHub release publication has not been approved or executed.",
		"straddle-pp-cli shipcheck local --json",
		"make release-readiness",
	} {
		if !strings.Contains(stdout, want) {
			t.Fatalf("benchmark ramp human output missing %q:\n%s", want, stdout)
		}
	}
}

func TestBenchmarkRampAgentEnvelope(t *testing.T) {
	stdout, stderr, err := runCLIForDocsTest(t, "benchmark", "ramp", "--agent")
	if err != nil {
		t.Fatalf("benchmark ramp --agent returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("benchmark ramp --agent wrote stderr: %q", stderr)
	}

	var got struct {
		SchemaVersion string                `json:"schema_version"`
		Data          benchmarkRampResponse `json:"data"`
		Warnings      []string              `json:"warnings"`
		Error         any                   `json:"error"`
	}
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("benchmark ramp --agent emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.SchemaVersion != "1.0" || got.Error != nil || len(got.Warnings) != 0 {
		t.Fatalf("wrong agent envelope: %#v", got)
	}
	if got.Data.Command != "benchmark ramp" || len(got.Data.Dimensions) == 0 {
		t.Fatalf("agent envelope missing benchmark data: %#v", got.Data)
	}
}

func TestBenchmarkRampRejectsProfileAndDeliver(t *testing.T) {
	if _, _, err := runCLIForDocsTest(t, "benchmark", "ramp", "--profile", "sandbox", "--json"); err == nil || !strings.Contains(err.Error(), "benchmark ramp does not support --profile") {
		t.Fatalf("benchmark ramp should reject --profile before loading config, got %v", err)
	}
	if _, _, err := runCLIForDocsTest(t, "benchmark", "ramp", "--deliver", "file:/tmp/benchmark.json", "--json"); err == nil || !strings.Contains(err.Error(), "benchmark ramp does not support --deliver") {
		t.Fatalf("benchmark ramp should reject --deliver before delivery, got %v", err)
	}
}
